## 3. Revised `app.js` (Secure Baseline)

Below is a **drop‑in replacement** that addresses the above items while staying minimal. You can copy‑paste it over the existing file; all new dependencies are listed afterward.

```js
/**
 * Secure version of app.js
 * -------------------------------------------------
 * - Uses Helmet for security headers
 * - Enables CORS with whitelist
 * - Adds request rate limiting
 * - Logs requests (Morgan) and centralises error handling
 * - Provides a simple JWT auth middleware (replace with your own strategy)
 * - Enforces HTTPS when behind a proxy (e.g., Heroku, AWS ELB)
 * -------------------------------------------------
 */

'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');          // npm i jsonwebtoken
const { body, validationResult, query } = require('express-validator'); // npm i express-validator

const app = express();

// -------------------------------------------------
// 1️⃣ Basic hardening middlewares
// -------------------------------------------------
app.use(helmet()); // sets HSTS, CSP, X‑Frame‑Options, etc.
app.use(express.json()); // parse JSON bodies (needed for future POST/PUT)
app.set('trust proxy', 1); // needed if app sits behind a reverse‑proxy (TLS termination)

// -------------------------------------------------
// 2️⃣ CORS – only allow known origins (adjust as needed)
// -------------------------------------------------
const allowedOrigins = ['https://my-frontend.example.com']; // <-- change to your domains
app.use(
  cors({
    origin: function (origin, callback) {
      // allow requests with no origin (like mobile apps or curl)
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      return callback(new Error('Not allowed by CORS'), false);
    },
    credentials: true,
  })
);

// -------------------------------------------------
// 3️⃣ Rate limiting – mitigate DoS & brute‑force
// -------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// -------------------------------------------------
// 4️⃣ Logging (Morgan) – stdout is captured by most container platforms
// -------------------------------------------------
app.use(morgan('combined'));

// -------------------------------------------------
// 5️⃣ Simple JWT authentication middleware
// -------------------------------------------------
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_ME_IN_PROD';
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401); // No token

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid token
    req.user = user; // attach decoded payload
    next();
  });
}

// -------------------------------------------------
// 6️⃣ Input validation helpers (example for future POST)
// -------------------------------------------------
const validateUserId = [
  query('id')
    .optional()
    .isInt({ gt: 0 })
    .toInt()
    .withMessage('id must be a positive integer'),
];

// -------------------------------------------------
// 7️⃣ Routes
// -------------------------------------------------

// Health check – keep it public, but hide stack traces on error
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * – Protected by JWT (replace with your own RBAC if needed)
 * – Returns a static list for demo purposes
 */
app.get('/users', authenticateToken, (req, res) => {
  // In a real system you would query a DB with a parameterised query.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

/**
 * Example of a POST endpoint with validation & sanitisation
 * (illustrates how to avoid injection and enforce input rules)
 */
app.post(
  '/users',
  authenticateToken,
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 50 })
      .withMessage('Name is required and must be ≤ 50 chars'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required'),
    // Add more fields as needed
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Pretend we insert safely with a parameterised DB call here
    const { name, email } = req.body;
    // e.g., db.query('INSERT INTO users (name,email) VALUES ($1,$2)', [name,email]);

    res.status(201).json({ message: 'User created', user: { name, email } });
  }
);

// -------------------------------------------------
// 8️⃣ Global error handler (does NOT leak stack traces)
// -------------------------------------------------
app.use((err, req, res, next) => {
  console.error(err); // you may replace with Winston/Bunyan for structured logs

  const status = err.status || 500;
  const response = {
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
    },
  };
  // In production you typically hide the stack, but you can enable it via NODE_ENV
  if (process.env.NODE_ENV !== 'production') {
    response.error.stack = err.stack;
  }
  res.status(status).json(response);
});

// -------------------------------------------------
// 9️⃣ Server start
// -------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What changed?

| Change | Why it matters |
|--------|----------------|
| `helmet()` | Adds a robust set of security headers (CSP, HSTS, X‑Content‑Type‑Options, …). |
| `cors()` with whitelist | Prevents browsers from allowing any origin to consume the API. |
| `express-rate-limit` | Throttles abusive IPs, mitigating brute‑force and DoS attacks. |
| `morgan` logging | Gives you audit trails for requests and errors. |
| JWT auth middleware (`authenticateToken`) | Provides a baseline **authentication** and **access control** layer. |
| `express-validator` usage example | Demonstrates **input validation & sanitisation** to block injection and type‑confusion attacks. |
| Centralised error handler | Stops stack traces (which contain internal paths) from being exposed in production. |
| `app.set('trust proxy', 1)` | Makes Express respect `X‑Forwarded‑Proto` for HTTPS redirect enforcement when behind a reverse proxy. |
| `process.env.JWT_SECRET` & `process.env.PORT` | Moves secrets and configs out of source code (protects against accidental commit). |

