  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "cors": "^2.8.5",
    "express-rate-limit": "^7.2.0",
    "morgan": "^1.10.0",
    "jsonwebtoken": "^9.0.0",
    "express-validator": "^7.0.1"
