## Recommended approach for a Node/Express service

Below is a **sample integration** that shows how to:

1. **Detect the runtime environment** (local dev vs. production).  
2. **Load secrets from a proper secrets manager** when running in production.  
3. **Fall back to a safe `.env` file only for local development** (never checked‑in).  

You can drop this code into a new module (e.g., `config.js`) and import it from `app.js`.

```js
/*****************************************************************
 * config.js – Centralised configuration & secret loading
 *
 * • In development: reads from a local .env file (dotenv)
 * • In production: fetches from a secrets manager (example: AWS
 *   Secrets Manager).  Adjust the provider to whatever you use.
 *****************************************************************/

const fs = require('fs');
const path = require('path');

const ENV = process.env.NODE_ENV?.trim() || 'development';

// ---------- 1️⃣ Development – .env ----------
if (ENV === 'development') {
  // Use dotenv only in dev; the .env file should be listed in .gitignore
  // and never committed.
  const dotenvPath = path.resolve(__dirname, '.env');

  if (fs.existsSync(dotenvPath)) {
    // eslint-disable-next-line global-require
    require('dotenv').config({ path: dotenvPath });
    console.log('✅ Loaded configuration from .env (development mode)');
  } else {
    console.warn('⚠️  No .env file found – using only built‑in defaults');
  }
}

// ---------- 2️⃣ Production – Secrets Manager ----------
async function loadProductionSecrets() {
  // Example: AWS Secrets Manager.
  // Replace with your own provider (Azure Key Vault, GCP Secret Manager,
  // HashiCorp Vault, etc.).  The idea is to fetch *only* the secrets you
  // need and inject them into process.env.
  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
  const secretId = process.env.SECRET_ID; // e.g. "my-app/prod"

  if (!secretId) {
    throw new Error('❌ SECRET_ID env var is required in production');
  }

  const command = new GetSecretValueCommand({ SecretId: secretId });
  const response = await client.send(command);

  // AWS returns either SecretString (JSON) or SecretBinary.
  const secretString = response.SecretString;
  if (!secretString) {
    throw new Error('❌ Secret retrieved but empty');
  }

  // Expect the secret to be a JSON object like:
  // { "DB_PASSWORD":"...", "JWT_SIGNING_KEY":"...", "API_KEY":"..." }
  const secretObj = JSON.parse(secretString);

  // Populate process.env – this mimics what dotenv does.
  Object.entries(secretObj).forEach(([key, value]) => {
    process.env[key] = value;
  });

  console.log('✅ Loaded secrets from AWS Secrets Manager');
}

// Execute the async loader **only** when we are in production.
// (We deliberately do NOT await here inside the top‑level; we expose a
// promise that the server bootstrap can await before listening.)
const secretLoadPromise = ENV === 'production' ? loadProductionSecrets() : Promise.resolve();

module.exports = {
  /** Returns a promise that resolves once all secrets are loaded. */
  ready: () => secretLoadPromise,

  /** Convenience getter – throws if a required key is missing. */
  requireEnv: (key) => {
    const value = process.env[key];
    if (value === undefined) {
      throw new Error(`❌ Missing required environment variable: ${key}`);
    }
    return value;
  },

  /** Current environment (development | production | test) */
  env: ENV,
};
```

