// app.js – Secure baseline for an Express API
require('dotenv').config();               // 1️⃣ Load env vars (port, secrets, etc.)

const express = require('express');
const helmet = require('helmet');         // 2️⃣ Secure HTTP headers
const cors   = require('cors');           // 3️⃣ CORS control
const rateLimit = require('express-rate-limit'); // 4️⃣ DoS protection
const morgan = require('morgan');         // 5️⃣ Request logging
const { celebrate, Joi, errors, Segments } = require('celebrate'); // 6️⃣ Input validation

const app = express();

// ---------------------------------------------------------------------
// 1️⃣ Global Middleware
// ---------------------------------------------------------------------
app.use(helmet());                         // Set security‑related headers
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' })); // Adjust per environment
app.use(express.json());                  // Parse JSON bodies
app.use(express.urlencoded({ extended: true }));
app.use(morgan('combined'));              // Centralised request logging

// ---------------------------------------------------------------------
// 2️⃣ Rate Limiting (A4 – Insecure Design)
// ---------------------------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,               // 15 minutes
  max: 100,                               // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter);            // Apply only to potentially sensitive routes

// ---------------------------------------------------------------------
// 3️⃣ Health Endpoint (public, no auth)
// ---------------------------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------------------------------------------------------------------
// 4️⃣ Users Endpoint – Example with input validation (A3 – Injection)
// ---------------------------------------------------------------------
// In a real app you would fetch users from a DB using parametrised queries.
// This demo returns static data but validates any future query params.
app.get(
  '/users',
  celebrate({
    [Segments.QUERY]: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      offset: Joi.number().integer().min(0).default(0),
    }),
  }),
  (req, res) => {
    const { limit, offset } = req.query;
    // Example: slice static array safely; real DB would use limit/offset params
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    const paged = allUsers.slice(offset, offset + limit);
    res.json(paged);
  }
);

// ---------------------------------------------------------------------
// 5️⃣ Centralised Error Handler (A10 – Logging & Monitoring)
// ---------------------------------------------------------------------
app.use(errors()); // Celebrate/Joi validation errors handler

app.use((err, req, res, next) => {
  // Log the full error for ops (avoid leaking details to clients)
  console.error(err);
  // Generic error response
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message,
  });
});

// ---------------------------------------------------------------------
// 6️⃣ 404 Handler (A1 – Broken Access Control)
// ---------------------------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------------------------------------------------------------------
// 7️⃣ Server start – Configurable port, HTTPS enforcement note
// ---------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

module.exports = app;
```

