```js
// config/secrets.js
require('dotenv').config();               // Loads .env only for local dev (git‑ignored)

// ---------- 1️⃣ Helper for AWS Secrets Manager (example) ----------
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretClient = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Fetch a secret from AWS Secrets Manager.
 * Returns the raw string value (for JSON secrets use JSON.parse afterwards).
 */
async function getAwsSecret(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await secretClient.send(command);
  return response.SecretString;
}

// ---------- 2️⃣ Centralised getter ----------
async function loadSecrets() {
  // Define the list of required secrets – change names to match your secret store
  const required = {
    DATABASE_URL:       'prod/db-url',            // secret name in the manager
    AWS_ACCESS_KEY_ID:  'prod/aws-access-key-id',
    AWS_SECRET_ACCESS_KEY: 'prod/aws-secret-access-key',
    ANTHROPIC_API_KEY:  'prod/anthropic-api-key',
    STRIPE_SECRET_KEY:  'prod/stripe-secret-key',
    LOGFIRE_TOKEN:      'prod/logfire-token',
  };

  const secrets = {};

  for (const [envVar, secretName] of Object.entries(required)) {
    // 1️⃣ Try the secret manager
    try {
      const value = await getAwsSecret(secretName);
      secrets[envVar] = value;
      continue;
    } catch (e) {
      // If the secret manager call fails (e.g., running locally), fall back to env var
      if (process.env[envVar]) {
        secrets[envVar] = process.env[envVar];
        continue;
      }
      // If both methods fail – abort early – you don’t want a partially‑configured app
      throw new Error(`Unable to load required secret: ${envVar}`);
    }
  }

  // Export the collected secrets as a frozen object (prevents accidental mutation)
  return Object.freeze(secrets);
}

module.exports = { loadSecrets };
```

