#### `middleware/auth.js`

```js
// middleware/auth.js
const jwt = require('jsonwebtoken');

const secret = process.env.JWT_SECRET || 'CHANGE_ME_IN_PROD';

function generateToken(payload, expiresIn = '1h') {
  return jwt.sign(payload, secret, { expiresIn });
}

/**
 * Express middleware that verifies a Bearer token.
 * If valid, `req.user` will contain the decoded payload.
 */
function verifyToken(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, secret);
    req.user = decoded;                 // you can use this for role‑based checks
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

module.exports = { generateToken, verifyToken };
```

#### Example login route (add to `app.js`)

