   // src/secrets/aws.js
   const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

   const region = process.env.AWS_REGION || 'us-east-1';
   const client = new SecretsManagerClient({ region });

   /**
    * Retrieves a secret (JSON string) from AWS Secrets Manager.
    * Caches the result in memory for the lifetime of the process.
    */
   const cache = new Map();

   async function getSecret(secretName) {
     // Return cached value if we already fetched it
     if (cache.has(secretName)) return cache.get(secretName);

     const command = new GetSecretValueCommand({ SecretId: secretName });
     const response = await client.send(command);

     // Secrets can be stored as a string or binary; we handle string only here.
     const secretString = response.SecretString;
     const parsed = JSON.parse(secretString); // Expect JSON like { "jwtSecret": "...", "dbPassword": "..."} 

     cache.set(secretName, parsed);
     return parsed;
   }

   module.exports = { getSecret };
   ```

