### 3.2 Refactored **app.js**

```js
// app.js
require('dotenv').config();               // <‑ load .env (PORT, JWT_SECRET, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

/* -------------------------------------------------
   1️⃣ Global Middleware
   ------------------------------------------------- */
app.use(helmet());                         // Sets secure HTTP headers (HSTS, CSP, etc.)
app.use(cors({                               // Adjust origins as needed
  origin: process.env.CORS_ORIGIN || '*', // Example: restrict to your frontend domain
  methods: ['GET','POST','PUT','DELETE'],
}));
app.use(express.json());                  // Body parser for JSON payloads
app.use(express.urlencoded({ extended: false }));

// Simple request logging – replace with winston for production
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

/* -------------------------------------------------
   2️⃣ Rate Limiting (basic DoS protection)
   ------------------------------------------------- */
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,  // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/api/', apiLimiter); // Apply only to API routes (you can broaden it)

/* -------------------------------------------------
   3️⃣ Authentication Helper
   ------------------------------------------------- */
// In a real app you would store users in a DB; here we keep a static list
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com', passwordHash: '$2a$10$...' }, // bcrypt hash
  { id: 2, name: 'Bob', email: 'bob@example.com', passwordHash: '$2a$10$...' },
];

/**
 * Middleware that validates the JWT and attaches the user object to req.user.
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) return res.sendStatus(401); // No token → unauthorized

  jwt.verify(token, process.env.JWT_SECRET, (err, payload) => {
    if (err) return res.sendStatus(403); // Invalid token → forbidden
    const user = users.find(u => u.id === payload.sub);
    if (!user) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

/* -------------------------------------------------
   4️⃣ Routes
   ------------------------------------------------- */

// Health check – minimal info, no timestamp
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

/**
 * Login endpoint – returns a signed JWT.
 * Demonstrates proper input validation & password hashing.
 */
app.post(
  '/login',
  body('email').isEmail(),
  body('password').isLength({ min: 6 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { email, password } = req.body;
    const user = users.find(u => u.email === email);
    if (!user) return res.status(401).json({ message: 'Invalid credentials' });

    const bcrypt = require('bcryptjs');
    if (!bcrypt.compareSync(password, user.passwordHash)) {
      return res.status(401).json({ message: 'Invalid credentials' });
    }

    // Issue short‑lived JWT (e.g., 15 min) + refresh token strategy in real apps
    const token = jwt.sign({ sub: user.id }, process.env.JWT_SECRET, {
      expiresIn: '15m',
    });

    res.json({ token });
  }
);

/**
 * Protected route – only authenticated users can list users.
 * In production you would filter based on role/permissions.
 */
app.get('/api/users', authenticateToken, (req, res) => {
  // NEVER expose password hashes or other secrets!
  const safeUsers = users.map(u => ({
    id: u.id,
    name: u.name,
    email: u.email,
  }));
  res.json(safeUsers);
});

/* -------------------------------------------------
   5️⃣ Error handling (centralised, no stack traces)
   ------------------------------------------------- */
app.use((err, req, res, next) => {
  console.error(err); // Replace with winston logger in prod
  const status = err.status || 500;
  const response = { message: err.message };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

/* -------------------------------------------------
   6️⃣ Server start
   ------------------------------------------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

