// config/secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const REGION = process.env.AWS_REGION || 'us-east-1';
const client = new SecretsManagerClient({ region: REGION });

/**
 * Retrieves a secret from AWS Secrets Manager and parses it as JSON.
 * Most teams store a single JSON blob per service (e.g., {"DB_PASSWORD": "..."}).
 */
async function loadSecret(secretName) {
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);
  const secretString = response.SecretString || Buffer.from(response.SecretBinary, 'base64').toString('utf-8');

  try {
    return JSON.parse(secretString);
  } catch {
    // If not JSON, return raw string (useful for single‑value secrets)
    return secretString;
  }
}

// Example usage – call during app bootstrap
async function initSecrets() {
  const secret = await loadSecret(process.env.AWS_SECRETS_MANAGER_ID);
