```js
// utils/logger.js (example using winston)
const { createLogger, format, transports } = require('winston');

const secretKeys = ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'JWT_SECRET', 'DATABASE_URL'];

const redacted = format((info) => {
  secretKeys.forEach((key) => {
    if (info[key]) {
      info[key] = '[REDACTED]';
    }
    // also redact if the key appears in message strings
    if (typeof info.message === 'string') {
      info.message = info.message.replace(new RegExp(info[key], 'g'), '[REDACTED]');
    }
  });
  return info;
});

const logger = createLogger({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  format: format.combine(redacted(), format.json()),
  transports: [new transports.Console()],
});

module.exports = logger;
```

Then replace `console.log` statements with `logger.info`, `logger.error`, etc.

