```js
// awsSecrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

async function getSecret(name) {
  const cmd = new GetSecretValueCommand({ SecretId: name });
  const { SecretString } = await client.send(cmd);
  return JSON.parse(SecretString);
}

// Usage (await at top‑level with an IIFE or during app init)
(async () => {
  const dbCreds = await getSecret('prod/database');   // returns { url: "...", user: "...", password: "..." }
  process.env.DATABASE_URL = dbCreds.url;   // optional – make it look like env vars for downstream code
})();
```

* **Security best‑practice:**  
