/**
 * Central configuration loader.
 *
 * - In **development** you may load a .env file with `dotenv`.
 * - In **production** rely on real environment variables injected by the platform.
 * - Optionally replace the `loadFromSecretsManager` function with AWS/GCP/Vault calls.
 */

const loadFromEnv = () => {
  const required = ['PORT', 'JWT_SECRET'];   // add any other required vars here
  required.forEach((key) => {
    if (!process.env[key]) {
      throw new Error(`Missing required environment variable ${key}`);
    }
  });

