  '/',
  authenticate,                               // <-- enforce authentication
  // Optional: validate "search" query param
  [
    check('search')
      .optional()
      .isString()
      .trim()
      .escape()
      .isLength({ max: 30 })
      .withMessage('Search term is too long')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { search } = req.query;
    const result = search
