### Example – Adding a Secure Secret Loader

Below is a minimal pattern that **still uses a `.env` for local development**, but **pulls the real secret from AWS Secrets Manager** when running in production:

```js
// config.js – centralised configuration
require('dotenv').config(); // loads .env locally (ignored by Git)

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function getSecret(secretName) {
  // In production, fetch from AWS Secrets Manager
  if (process.env.NODE_ENV === 'production') {
    const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const { SecretString } = await client.send(command);
    return SecretString ? JSON.parse(SecretString) : {};
  }
  // In dev, fall back to .env values
  return {
    jwtSecret: process.env.JWT_SECRET,
    dbPassword: process.env.DB_PASSWORD,
    // …other dev secrets
  };
}

module.exports = { getSecret };
```

Then in `app.js`:

```js
const { getSecret } = require('./config');

(async () => {
  const { jwtSecret, dbPassword } = await getSecret('myApp/prod'); // name of secret in AWS

  if (!jwtSecret) {
    console.error('Missing JWT secret – aborting startup.');
    process.exit(1);
  }

  // Use jwtSecret in your JWT middleware, dbPassword for your DB client, etc.
  // ... rest of the server setup
})();
```

*When running locally, `dotenv` supplies the variables; in production the code pulls the real secret from the manager.*  

