## Example of a “complete” startup flow using **environment variables** and **fallback to AWS Secrets Manager** (you can cherry‑pick what fits your environment)

```js
// start.js – central entry point
require('dotenv').config(); // loads .env for local dev only

const { getSecret } = require('./secrets'); // AWS wrapper from earlier

(async () => {
  // 1️⃣ Prefer explicit env vars (useful for Docker/K8s)
  const cfg = {
    PORT: process.env.PORT || 3000,
    DATABASE_URL: process.env.DATABASE_URL,
    JWT_SECRET: process.env.JWT_SECRET,
    // add others as needed...
  };

  // 2️⃣ If any required var is missing, try to fetch from Secrets Manager
  const missing = Object.entries(cfg)
    .filter(([, v]) => !v)
    .map(([k]) => k);

  if (missing.length) {
    console.log(`⚠️  Missing env vars: ${missing.join(', ')} – trying Secrets Manager`);
    try {
      const secret = await getSecret('prod/myapp/config');
      missing.forEach((name) => {
        cfg[name] = secret[name];
      });
    } catch (e) {
      console.error('❌ Could not retrieve missing secrets:', e);
      process.exit(1);
    }
  }

  // 3️⃣ Validate that everything we need is now present
  ['DATABASE_URL', 'JWT_SECRET'].forEach((name) => {
    if (!cfg[name]) {
      console.error(`❌ Critical config ${name} is still missing`);
      process.exit(1);
    }
  });

  // 4️⃣ Pass the config to the app
  const createApp = require('./app');   // modify app.js to export a factory: (cfg) => express()
  const app = createApp(cfg);

  app.listen(cfg.PORT, () => console.log(`🚀 Server listening on ${cfg.PORT}`));
})();
```

*You would refactor `app.js` so that it **receives** its configuration instead of pulling `process.env` directly; this makes the code testable and clearly separates “configuration” from “implementation”.*

