### 3.2. Revised `app.js`

```js
// app.js
require('dotenv').config();               // Load env vars from .env (never commit this file)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

const app = express();

// ---------- 1. Global Middleware ----------
app.use(helmet());                         // Set security headers (CSP, HSTS, etc.)
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') || '*' })); // Restrict origins
app.use(express.json());                  // Parse JSON bodies
app.use(morgan('combined'));               // Production‑grade request logging

// ---------- 2. Rate Limiting ----------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // max 100 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, try again later.' }
});
app.use('/api/', apiLimiter); // Apply to all API routes

// ---------- 3. Simple in‑memory user store (for demo) ----------
/*
 * In a real app this would be a DB with hashed passwords.  We're keeping
 * it minimal here to illustrate authentication.
 */
const users = [
  {
    id: 1,
    name: 'Alice',
    email: 'alice@example.com',
    // password: bcrypt hash of "password123"
    passwordHash: bcrypt.hashSync('password123', 10),
    role: 'admin'
  },
  {
    id: 2,
    name: 'Bob',
    email: 'bob@example.com',
    passwordHash: bcrypt.hashSync('mySecret!456', 10),
    role: 'user'
  }
];

// ---------- 4. Auth Helpers ----------
const JWT_SECRET = process.env.JWT_SECRET || 'change-me-please';
const JWT_EXPIRES_IN = '1h';

function generateToken(user) {
  return jwt.sign({ sub: user.id, role: user.role }, JWT_SECRET, {
    expiresIn: JWT_EXPIRES_IN
  });
}

/**
 * Middleware that verifies a JWT and adds `req.user`.
 * Returns 401 if missing/invalid.
 */
function authenticateJWT(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = payload; // { sub: <id>, role: <role>, iat, exp }
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

/**
 * Role‑based access control – pass one or more allowed roles.
 */
function authorizeRoles(...allowed) {
  return (req, res, next) => {
    if (!req.user || !allowed.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
}

// ---------- 5. Auth Endpoints ----------
app.post('/api/login', (req, res) => {
  const { email, password } = req.body;
  // Simple validation (use express‑validator for production)
  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  const user = users.find(u => u.email === email);
  if (!user || !bcrypt.compareSync(password, user.passwordHash)) {
    // Avoid user enumeration – generic message
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = generateToken(user);
  res.json({ token });
});

// ---------- 6. Public Endpoints ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------- 7. Protected Endpoints ----------
/**
 * Example: only authenticated users can see the user list.
 * In a real service you would drop or mask sensitive fields (e.g., email)
 * or require admin role for full details.
 */
app.get(
  '/api/users',
  authenticateJWT,
  authorizeRoles('admin', 'user'), // both roles allowed for demo
  (req, res) => {
    // Strip password hashes before sending data
    const safeUsers = users.map(({ passwordHash, ...rest }) => rest);
    res.json(safeUsers);
  }
);

// ---------- 8. Catch‑all error handler ----------
app.use((err, req, res, next) => {
  // Log the error – in production replace console with a proper logger
  console.error(err);
  // Do NOT leak stack traces to the client in production
  const status = err.status || 500;
  const response = { error: err.message || 'Internal Server Error' };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

// ---------- 9. Server ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

module.exports = app;
```

